    assert(solution.countSegments("Multiple    spaces between words") == vector<int>4);
    assert(solution.countSegments("   Hello) == vector<int>5);
    assert(solution.countSegments("Leading and trailing spaces should be ignored   ") == vector<int>7);
    assert(solution.countSegments("Punctuation) == vector<int>5);
    assert(solution.countSegments("123 456 789 0") == vector<int>4);
    assert(solution.countSegments("Mixing\t\nand\tspecial\t\ncharacters") == vector<int>4);
    assert(solution.countSegments("Multiple   spaces   between words") == vector<int>4);
    assert(solution.countSegments(" Leading and trailing spaces ") == vector<int>4);
    assert(solution.countSegments("\tTabs\tare\tconsidered\tspaces") == vector<int>4);
    assert(solution.countSegments("\t\t\tTabbed\t\t\tSegments\t\t\t") == vector<int>2);
    assert(solution.countSegments("  a  b  c  d  e  ") == vector<int>5);
    assert(solution.countSegments("\u0020\u0020\u0020Unicode\u0020spaces\u0020\u0020\u0020") == vector<int>2);
    assert(solution.countSegments("    a   b   c   ") == vector<int>3);
    assert(solution.countSegments("   ") == vector<int>0);
    assert(solution.countSegments("Hello\tmy\tname\tis\tJohn") == vector<int>5);
    assert(solution.countSegments("    ") == vector<int>0);
    assert(solution.countSegments("\nNew\nlines\nare\nspaces\ntoo") == vector<int>5);
    assert(solution.countSegments("Punctuation) == vector<int>6);
    assert(solution.countSegments("Multiple     spaces   between   words") == vector<int>4);
    assert(solution.countSegments("   Hello) == vector<int>5);
    assert(solution.countSegments("a b c d e f g") == vector<int>7);
    assert(solution.countSegments("Hello    my     name    is    John") == vector<int>5);
    assert(solution.countSegments("\tTabs\tare\tcounted\tas\tspaces") == vector<int>5);
    assert(solution.countSegments("Mixed\tTabs\t\tand\t\t\tSpaces") == vector<int>4);
    assert(solution.countSegments("   Leading and trailing spaces   ") == vector<int>4);
    assert(solution.countSegments("Multiple    spaces    between   words") == vector<int>4);
    assert(solution.countSegments("SingleWord") == vector<int>1);
    assert(solution.countSegments("Tab	Separated") == vector<int>2);
    assert(solution.countSegments("\nHello\nmy\nname\nis\nJohn\n") == vector<int>5);
}

